&= \|\overrightarrow{A} - \overrightarrow{B}\|^2 + \|2 \overrightarrow{A} + \overrightarrow{B} + \overrightarrow{C}\|^2 + \|\overrightarrow{A} + 2 \overrightarrow{B} + \overrightarrow{C}\|^2 \\
